package io.github.gbalazsfalvi.fuzzy.experiments;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Runs the frozen local exploratory comparison, or checks its saved manifest and numerical files.
 *
 * <p>Timing observations are not regenerated by verification. Numerical payloads, configuration
 * hashes, method order, and diagnostics are checked against the declared protocol.
 */
public final class ComparisonDemo {
  private ComparisonDemo() {}

  /**
   * Generates or verifies the local comparison evidence.
   *
   * @param args none, --verify directory, or --protocol file --output directory
   * @throws IOException if the protocol or evidence cannot be read or written
   * @throws IllegalArgumentException if syntax, provenance, or saved numerical evidence is invalid
   */
  public static void main(String[] args) throws IOException {
    Path root = Path.of("").toAbsolutePath();
    if (args.length == 2 && "--verify".equals(args[0])) {
      Path directory = Path.of(args[1]);
      ComparisonEvidence.Archive archive = ComparisonReports.read(directory);
      if (!archive.sourceSha256().equals(FoundationDemo.sourceDigest(root))) {
        throw new IllegalArgumentException(
            "The comparison source digest differs from this implementation.");
      }
      int count = ComparisonReports.verify(directory, archive, System.out::println);
      System.out.println(
          "Verified " + count + " numerical runs, their complete cohort, and saved diagnostics.");
      return;
    }
    if (args.length != 0
        && (args.length != 4 || !"--protocol".equals(args[0]) || !"--output".equals(args[2]))) {
      throw new IllegalArgumentException(
          "Usage: comparisonDemo [--protocol <file> --output <directory> | --verify <directory>]");
    }
    Path protocolFile =
        Path.of(args.length == 0 ? "research/protocols/milestone-03-pilot-v1.json" : args[1]);
    Path output = Path.of(args.length == 0 ? "artifacts/comparison" : args[3]);
    ComparisonProtocol protocol =
        EvidenceJson.FORMAT.fromJson(
            Files.readString(protocolFile, StandardCharsets.UTF_8), ComparisonProtocol.class);
    if (protocol == null) {
      throw new IllegalArgumentException("The comparison protocol cannot be null.");
    }
    ComparisonEvidence.Archive archive =
        ComparisonRunner.run(root, protocol, output, System.out::println);
    ComparisonReports.write(output, archive);
    System.out.println("Comparison evidence: " + output.toAbsolutePath());
  }
}
